/* Mobile research, versioned book editor and paginated reader. */
const previousUI={shell,navigate,renderReader,renderReaderContent,card,ideaModal};
const newId=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const assetUrl=(id,preview=true)=>'/api/asset?id='+encodeURIComponent(id)+(preview?'&preview=1':'');
let activeBookId='book-main';try{activeBookId=localStorage.getItem('atelier-last-book')||'book-main'}catch{}
const baseApi=api;
api=async function(path,data){if(data===undefined&&['library','history','book-sections','book'].includes(path))path+='?book_id='+encodeURIComponent(activeBookId);return baseApi(path,data)};
function rememberBook(id){activeBookId=id;try{localStorage.setItem('atelier-last-book',id)}catch{}}
const fullDate=s=>new Date(s).toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'});
let bookDraft=null,bookDirty=false,bookSaving=false,bookEpoch=0,saveTimer=null,bookConflict=false,chapterId=null;
let reading=null,readingIndex=0,readingFont=17,readingAbort=null,readingResize=null;
function statusText(text,error=false){const e=$('#saveStatus');if(e){e.textContent=text;e.classList.toggle('error',error)}}

shell=function(content){
  previousUI.shell(content);
  $('.app').classList.toggle('book-workspace',view==='book');
  const mobile=document.createElement('nav');mobile.className='mobile-nav';mobile.setAttribute('aria-label','Navigation mobile');
  mobile.innerHTML=[['library','▦','Sources'],['ideas','✧','Idées'],['folders','▱','Dossiers'],['book','▤','Livre'],['settings','⚙','Réglages']].map(([v,i,l])=>`<button data-mobile-nav="${v}" class="${view===v||(view==='reader'&&v==='library')?'active':''}"><span aria-hidden="true">${uiIcon(i)}</span><small>${l}</small></button>`).join('');
  $('.app').append(mobile);$$('[data-mobile-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.mobileNav));
  if(view==='book'){
    const switcher=document.createElement('div');switcher.className='project-switcher';switcher.innerHTML=`<label for="bookProject">Projet de livre</label><select id="bookProject">${(state.books||[]).map(b=>`<option value="${esc(b.id)}" ${b.id===state.book._book_id?'selected':''}>${esc(b.title)}</option>`).join('')}</select><button id="newBookProject"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v14M5 12h14"/></svg> Nouveau livre</button>`;$('.heading').before(switcher);
    $('#bookProject').onchange=e=>run(async()=>{await persistDraft();rememberBook(e.target.value);await reload();bookDraft=null;chapterId=null;renderBook()});$('#newBookProject').onclick=newBookModal;
  }
};
navigate=function(v){
  if(view==='book'&&bookDirty){
    showModal(`<h2>Votre texte n’est pas encore enregistré</h2><p>Gardez votre brouillon en enregistrant avant de changer d’écran.</p><div class="modal-actions"><button data-close>Rester ici</button><button id="leaveSave" class="primary">Enregistrer et continuer</button></div>`);
    $('#leaveSave').onclick=e=>run(async()=>{await persistDraft();if(bookDirty)return;$('#modal').close();previousUI.navigate(v)},e.currentTarget);return;
  }
  if(v!=='book')bookDraft=null;
  previousUI.navigate(v);
};
window.addEventListener('beforeunload',e=>{if(bookDirty){e.preventDefault();e.returnValue=''}});

card=function(s){let markup=previousUI.card(s);if(s.preview_id)markup=markup.replace('<div class="document-cover">Aa</div>',`<img src="${assetUrl(s.preview_id)}" alt="" loading="lazy">`);return markup.replace(s.segment_count?'✓ Transcription':'Texte manquant',s.kind==='Image'?'Image':s.kind==='PDF'?'PDF · '+s.page_count+' pages':s.kind==='EPUB'?'Livre EPUB':s.segment_count?'✓ Texte disponible':'Texte manquant')};

async function uploadFile(file,meta={},asSource=true,onProgress=()=>{}){
  if(!file||file.size>30*1024*1024)throw Error('Chaque fichier doit peser au maximum 30 Mo.');
  const params=new URLSearchParams({name:file.name,title:meta.title||'',author:meta.author||'',source:asSource?'1':'0'});
  return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/upload?'+params);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress(Math.round(e.loaded/e.total*100))};xhr.onload=()=>{let result;try{result=JSON.parse(xhr.responseText)}catch{return reject(Error('Le serveur a interrompu cet import.'))}if(xhr.status===401){renderLogin();return reject(Error('Reconnectez-vous.'))}if(xhr.status>=400)return reject(Error(result.error||'Import impossible.'));resolve(result)};xhr.onerror=()=>reject(Error('Connexion interrompue. Le fichier n’a pas pu être envoyé.'));xhr.send(file)});
}
importModal=function(){
  showModal(`<div class="eyebrow">Enrichir la bibliothèque</div><h2>Ajouter une source</h2><div class="import-tabs" role="tablist"><button class="active" data-import-tab="files" role="tab" aria-selected="true">Fichiers</button><button data-import-tab="youtube" role="tab" aria-selected="false">YouTube</button><button data-import-tab="text" role="tab" aria-selected="false">Texte / lien</button></div><div id="importBody"></div>`);
  const show=t=>{$$('[data-import-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.importTab===t);b.setAttribute('aria-selected',String(b.dataset.importTab===t))});
    if(t==='files'){
      $('#importBody').innerHTML=`<form id="filesForm"><label class="upload-zone"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v14M5 12h14"/></svg><strong>Choisir des fichiers</strong><span>Photos, schémas, PDF, EPUB, DOCX, texte…<br>30 Mo par fichier · plusieurs fichiers possibles</span><input id="sourceFiles" type="file" multiple required></label><div id="fileSelection" class="small"></div><label>Titre (facultatif, pour un seul fichier)<input id="fileTitle" placeholder="Le nom du document sera utilisé"></label><label>Auteur (facultatif)<input id="fileAuthor" placeholder="Détecté dans le fichier si disponible"></label><p class="small">L’original est conservé. Les PDF numérisés restent consultables sans reconnaissance de texte. Les formats non reconnus sont conservés comme pièces jointes.</p><progress id="fileProgress" max="100" value="0" hidden></progress><p id="uploadStatus" role="status"></p>${formActions('Importer')}</form>`;
      $('#sourceFiles').onchange=e=>$('#fileSelection').textContent=Array.from(e.target.files).map(f=>`${f.name} · ${(f.size/1024/1024).toFixed(1)} Mo`).join(' / ');
      $('#filesForm').onsubmit=e=>{e.preventDefault();run(async()=>{const files=[...$('#sourceFiles').files];if(files.length>20)throw Error('Importez au maximum 20 fichiers à la fois.');$('#fileProgress').hidden=false;const errors=[];let done=0;for(const f of files){$('#uploadStatus').textContent=`${done+1}/${files.length} · ${f.name}`;try{await uploadFile(f,{title:files.length===1?$('#fileTitle').value:'',author:$('#fileAuthor').value},true,n=>{if($('#fileProgress'))$('#fileProgress').value=n});done++}catch(err){errors.push(f.name+' : '+err.message)}}await reload();view='library';query='';author='';status='';kind='';tag='';folder='';scope='all';sort='added';page=1;renderLibrary();if(errors.length){$('#uploadStatus').textContent=`${done} fichier(s) importé(s). ${errors.join(' / ')}`;$('#uploadStatus').className='error'}else{$('#modal').close();toast(`${done} source(s) ajoutée(s).`)}},e.submitter)};
    }else if(t==='youtube'){
      $('#importBody').innerHTML=`<form id="youtubeForm"><label>Lien de la vidéo<input name="url" type="url" required placeholder="https://youtu.be/…" inputmode="url"></label><label>Titre (facultatif)<input name="title" placeholder="Récupéré depuis YouTube"></label><p class="small">Le titre, l’auteur et les sous-titres disponibles seront recherchés. Si YouTube refuse la collecte, la vidéo reste accessible et vous pourrez coller son texte.</p>${formActions('Ajouter la vidéo')}</form>`;
      $('#youtubeForm').onsubmit=e=>{e.preventDefault();run(async()=>{const result=await api('youtube',Object.fromEntries(new FormData(e.target)));await reload();$('#modal').close();view='library';query='';status='';folder='';sort='added';render();toast(result.already_present?'Cette vidéo est déjà dans la bibliothèque.':'Vidéo ajoutée. Récupération du texte en cours.')},e.submitter)};
    }else{
      $('#importBody').innerHTML=`<form id="sourceTextForm"><label>Titre<input name="title" required></label><label>Auteur<input name="author" required></label><label>Lien d’origine (facultatif)<input name="url" type="url" placeholder="https://…"></label><label>Type<select name="kind"><option>Article</option><option>Document</option><option>Entretien</option><option>Livre</option></select></label><label>Texte<textarea name="text" required rows="8" placeholder="Collez le texte à conserver et à analyser…"></textarea></label>${formActions('Ajouter')}</form>`;
      $('#sourceTextForm').onsubmit=e=>{e.preventDefault();run(async()=>{await api('import',Object.fromEntries(new FormData(e.target)));await reload();$('#modal').close();view='library';query='';status='';render()},e.submitter)};
    }
    $$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());
  };$$('[data-import-tab]').forEach(b=>b.onclick=()=>show(b.dataset.importTab));show('files');
};

renderReader=function(){
  previousUI.renderReader();
  const s=current;if(!s)return;
  const panel=$('#videoContainer');
  if(s.asset_id){panel.innerHTML=`<div class="source-preview">${s.kind==='PDF'?`<img id="pdfPreview" src="/api/pdf-page?id=${encodeURIComponent(s.asset_id)}&page=1" alt="Page 1 du document"><div class="row pdf-pager"><button id="pdfPrev" aria-label="Page précédente"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 5-7 7 7 7M5 12h14"/></svg></button><label>Page <input id="pdfPage" type="number" min="1" max="${s.page_count}" value="1" aria-label="Numéro de page"></label><span>/ ${s.page_count}</span><button id="pdfNext" aria-label="Page suivante"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 5 7 7-7 7M5 12h14"/></svg></button></div>`:s.preview_id?`<img src="${assetUrl(s.preview_id)}" alt="${esc(s.title)}">`:`<div class="document-cover">${uiIcon("▤")}</div>`}</div><div class="row source-file-actions"><a class="button-link" href="${assetUrl(s.asset_id,false)}"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/></svg> Original</a>${s.kind==='EPUB'||s.segments.length?'<button id="readDocument" class="primary"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v16M12 5C9 3 5 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 1Z"/></svg> Lire par pages</button>':''}<button id="editSource">Décrire / modifier</button></div>${s.warning?`<div class="notice">${esc(s.warning)}</div>`:''}`;
    $('#pdfPrev')?.addEventListener('click',()=>pdfTurn(-1));$('#pdfNext')?.addEventListener('click',()=>pdfTurn(1));$('#pdfPage')?.addEventListener('change',()=>pdfTurn(0));$('#readDocument')?.addEventListener('click',()=>openSourcePages(s));$('#editSource').onclick=sourceEditModal;
  }else if(!s.segments.length){const d=document.createElement('div');d.className='notice';d.innerHTML=`${esc(s.warning||'Ajoutez une transcription pour extraire des idées.')} <div class="row"><button id="addSourceText">Ajouter le texte</button>${yt(s)?'<button id="refetchSource">Relancer la récupération</button>':''}</div>`;panel.after(d);$('#addSourceText').onclick=sourceEditModal;$('#refetchSource')?.addEventListener('click',e=>run(async()=>{await api('refetch-transcript',{id:s.id});await reload();render();toast('Nouvelle tentative de récupération lancée.')},e.currentTarget))}
  if(s.kind!=='Vidéo'&&s.kind!=='Short'){$('[data-reader="text"]').textContent='Texte';}
  if(s.kind!=='Vidéo'&&s.kind!=='Short')$('#addChapter')?.closest('section')?.remove();
  if(matchMedia('(max-width:760px)').matches){
    const notes=$('#saveAnnotation')?.closest('section');
    if(notes){const details=document.createElement('details');details.className='mobile-reader-notes';details.innerHTML='<summary>Notes, tags et classement</summary>';notes.before(details);details.append(notes);$('.reader').append(details)}
  }
};
function pdfTurn(delta){const input=$('#pdfPage');const n=Math.max(1,Math.min(current.page_count,Number(input.value)+delta));input.value=n;$('#pdfPreview').src='/api/pdf-page?id='+encodeURIComponent(current.asset_id)+'&page='+n;$('#pdfPreview').alt='Page '+n;$('#pdfPrev').disabled=n===1;$('#pdfNext').disabled=n===current.page_count}
renderReaderContent=function(){
  previousUI.renderReaderContent();
  if(readerTab==='text'&&current?.kind!=='Vidéo'&&current?.kind!=='Short'){
    $$('.segment').forEach(el=>{
      const i=Number(el.id.replace('seg-','')),seg=current.segments[i],b=el.querySelector('.time');
      if(b){
        b.textContent=seg.page?'p. '+seg.page:seg.section?'§':'¶';b.title=seg.page?'Page '+seg.page:seg.section||'Passage '+(i+1);b.setAttribute('aria-label',b.title);
        b.onclick=()=>{if(seg.page&&$('#pdfPage')){$('#pdfPage').value=seg.page;pdfTurn(0);$('#videoContainer').scrollIntoView({behavior:'smooth'})}};
      }
    });
  }
};

function sourceEditModal(){showModal(`<h2>Compléter la source</h2><form id="editSourceForm"><label>Titre<input name="title" value="${esc(current.title)}" required></label><label>Auteur<input name="author" value="${esc(current.author)}" required></label><label>Description ou transcription à ajouter<textarea name="text" rows="8" placeholder="Ce texte remplacera le texte extrait si vous remplissez ce champ."></textarea></label><p class="small">Le fichier original reste conservé. Laissez le texte vide pour modifier seulement le titre ou l’auteur.</p>${formActions()}</form>`);$('#editSourceForm').onsubmit=e=>{e.preventDefault();run(async()=>{const d=Object.fromEntries(new FormData(e.target));if(!d.text.trim())delete d.text;await api('source-edit',{...d,id:current.id});current=await api('source?id='+current.id);await reload();$('#modal').close();renderReader()},e.submitter)}}

function ensureDraft(){if(!bookDraft){bookDraft=structuredClone(state.book);bookDirty=false;bookConflict=false}if(!bookDraft.chapters.find(c=>c.id===chapterId))chapterId=bookDraft.chapters[0]?.id||null;return bookDraft}
function currentChapter(){return bookDraft.chapters.find(c=>c.id===chapterId)}
function changed(label='Modification du livre'){bookDirty=true;bookEpoch++;bookDraft._label=label;statusText('Modifications en attente…');clearTimeout(saveTimer);if(!bookConflict)saveTimer=setTimeout(()=>persistDraft().catch(()=>{}),1600)}
async function persistDraft(){
  clearTimeout(saveTimer);if(bookSaving){await new Promise(resolve=>{const i=setInterval(()=>{if(!bookSaving){clearInterval(i);resolve()}},60)});if(bookDirty)return persistDraft();return}
  if(!bookDirty)return;
  if(bookConflict)throw Error('Résolvez le conflit de versions avant de continuer.');
  bookSaving=true;statusText('Enregistrement…');const epoch=bookEpoch,snapshot=structuredClone(bookDraft);
  try{const result=await api('book',snapshot);state.book=result;if(state.books){const summary=state.books.find(b=>b.id===result._book_id);if(summary){summary.title=result.title;summary.chapters=result.chapters.length}}bookDraft._revision=result._revision;bookDirty=bookEpoch!==epoch;statusText(bookDirty?'Nouvelles modifications…':'✓ Enregistré · '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}));if(bookDirty)saveTimer=setTimeout(()=>persistDraft().catch(()=>{}),1000)}
  catch(e){statusText('Échec de l’enregistrement · brouillon conservé',true);if(e.message.includes('autre appareil')){bookConflict=true;conflictModal()}else toast(e.message);throw e}
  finally{bookSaving=false}
}
saveBook=async function(book){state.book=await api('book',book);if(!bookDirty)bookDraft=structuredClone(state.book)};
function conflictModal(){showModal(`<h2>Deux versions du livre</h2><p>Une autre session a enregistré des modifications. Votre brouillon reste ici ; téléchargez-le avant de recharger la version du serveur.</p><div class="modal-actions"><button id="copyDraft">Télécharger mon brouillon</button><button data-close>Rester ici</button><button id="reloadBook" class="primary">Charger la version du serveur</button></div>`);$('#copyDraft').onclick=()=>download('brouillon-livre.json',JSON.stringify(bookDraft,null,2),'application/json');$('#reloadBook').onclick=()=>run(async()=>{await reload();bookDraft=null;bookDirty=false;bookConflict=false;$('#modal').close();renderBook()})}
function newBookModal(){showModal(`<h2>Un nouveau projet de livre</h2><p class="small">Le plan, le texte et l’historique seront indépendants. Les sources de la bibliothèque pourront être réutilisées.</p><form id="newBookForm"><label>Titre du projet<input name="title" placeholder="Ex. Mon guide de création d’entreprise" required></label><label>Auteur<input name="author"></label>${formActions('Créer le livre')}</form>`);$('#newBookForm').onsubmit=e=>{e.preventDefault();run(async()=>{await persistDraft();const b=await api('book-create',Object.fromEntries(new FormData(e.target)));rememberBook(b._book_id);await reload();bookDraft=null;chapterId=null;$('#modal').close();renderBook()},e.submitter)}}
renderBook=function(){
  const b=ensureDraft(),ch=currentChapter();
  shell(header('Atelier d’écriture','Votre livre','Écrire, illustrer et retrouver chaque modification.',`<button id="bookHistory"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M3 11a9 9 0 1 1 2.5 7M3 4v7h7m2-4v5l3 2"/></svg> Historique</button><button class="primary" id="readBook"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v16M12 5C9 3 5 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 1Z"/></svg> Lire le livre</button>`)+`<div class="book-command"><div><span id="saveStatus" role="status">${bookDirty?'Modifications en attente…':'✓ Toutes les modifications sont enregistrées'}</span><span class="small">Enregistrement automatique · versions datées</span></div><button id="saveNow">Enregistrer</button><button id="bookCovers">Couvertures</button><button id="mediaLibrary">Médiathèque</button><button id="exportOptions"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/></svg> Exporter</button><button id="bookLayout">Aa Mise en page</button></div><div class="writer-layout"><aside class="writer-outline"><details open><summary>Le livre · ${b.chapters.length} chapitres</summary><button id="bookDetails" class="outline-title">${esc(b.title)}</button><div class="chapter-outline">${b.chapters.map((c,n)=>`<button class="${c.id===chapterId?'active':''}" data-chapter-id="${esc(c.id)}"><small>${String(n+1).padStart(2,'0')}</small><span>${esc(c.title)}</span></button>`).join('')}</div><button id="addBookChapter"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v14M5 12h14"/></svg> Nouveau chapitre</button></details><div class="writer-tip">Du texte, une image, une citation : construisez chaque chapitre par blocs. Vos versions précédentes restent accessibles.</div></aside><section class="manuscript">${ch?`<div class="chapter-toolbar"><span class="eyebrow">CHAPITRE ${b.chapters.indexOf(ch)+1}</span><span class="grow"></span><button id="chapterUp" ${b.chapters.indexOf(ch)?'':'disabled'} aria-label="Monter le chapitre"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m5 12 7-7 7 7M12 5v14"/></svg></button><button id="chapterDown" ${b.chapters.indexOf(ch)===b.chapters.length-1?'disabled':''} aria-label="Descendre le chapitre"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m5 12 7 7 7-7M12 5v14"/></svg></button><button id="deleteChapter">Retirer</button></div><label class="sr-only" for="chapterTitle">Titre du chapitre</label><input id="chapterTitle" class="manuscript-title" value="${esc(ch.title)}" placeholder="Titre du chapitre"><div id="bookBlocks">${ch.blocks.map((block,n)=>blockEditor(block,n)).join('')}</div><div class="insert-bar"><button data-add-block="text"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v14M5 12h14"/></svg> Texte</button><button data-add-block="heading"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v14M5 12h14"/></svg> Intertitre</button><button data-add-block="quote"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M10 5H4v7h6v3a4 4 0 0 1-4 4m14-14h-6v7h6v3a4 4 0 0 1-4 4"/></svg> Citation</button><button id="insertImage"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/></svg> Image</button><button data-add-block="pagebreak">Saut de page</button></div><details class="chapter-evidence"><summary>Idées & références (${ch.ideas.length})</summary><p class="small">Ajoutez une idée depuis « Idées ». Ces passages sourcés figurent après le texte du chapitre, dans la lecture et les exports.</p>${ch.ideas.map(id=>state.ideas.find(i=>i.id===id)).filter(Boolean).map(i=>`<div class="book-idea"><span>${esc(i.title)}</span><button data-detach-idea="${esc(i.id)}" aria-label="Retirer cette référence"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m6 6 12 12M6 18 18 6"/></svg></button></div>`).join('')}</details>`:`<div class="empty"><span class="book-empty-icon"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v16M12 5C9 3 5 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 1Z"/></svg></span><h2>La première page vous attend.</h2><p>Créez un chapitre pour commencer à écrire.</p><button id="firstChapter" class="primary"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 5v14M5 12h14"/></svg> Mon premier chapitre</button></div>`}</section></div>`);
  $('#bookHistory').onclick=()=>run(async()=>{await persistDraft();await historyModal()});$('#readBook').onclick=()=>run(async()=>{await persistDraft();const data=await api('book-sections');const covers=data.book.covers||{};const sections=[];if(covers.front)sections.push({title:'Couverture',blocks:[{type:'image',asset_id:covers.front,alt:'Couverture'}]});sections.push(...data.sections);if(covers.back)sections.push({title:'Quatrième de couverture',blocks:[{type:'image',asset_id:covers.back,alt:'Quatrième de couverture'}]});await openPages({title:data.book.title,subtitle:data.book.subtitle,author:data.book.author,sections,book:!covers.front})});$('#saveNow').onclick=()=>run(persistDraft);$('#bookCovers').onclick=coverModal;$('#mediaLibrary').onclick=mediaLibraryModal;$('#bookLayout').onclick=layoutModal;$('#bookDetails').onclick=bookDetailsModal;$('#exportOptions').onclick=exportModal;$('#addBookChapter').onclick=addChapterToBook;$('#firstChapter')?.addEventListener('click',addChapterToBook);
  $$('[data-chapter-id]').forEach(btn=>btn.onclick=()=>{chapterId=btn.dataset.chapterId;renderBook()});
  if(ch){$('#chapterTitle').oninput=e=>{ch.title=e.target.value;changed('Titre du chapitre');const label=$(`[data-chapter-id="${chapterId}"] span`);if(label)label.textContent=ch.title};$('#chapterUp').onclick=()=>moveChapter(-1);$('#chapterDown').onclick=()=>moveChapter(1);$('#deleteChapter').onclick=deleteChapter;
    $$('[data-block-text]').forEach(t=>t.oninput=()=>{ch.blocks.find(b=>b.id===t.dataset.blockText).text=t.value;changed('Texte · '+ch.title)});
    $$('[data-block-caption]').forEach(t=>t.oninput=()=>{ch.blocks.find(b=>b.id===t.dataset.blockCaption).caption=t.value;changed('Légende · '+ch.title)});
    $$('[data-block-width]').forEach(t=>t.onchange=()=>{ch.blocks.find(b=>b.id===t.dataset.blockWidth).width=Number(t.value);changed('Taille d’image · '+ch.title)});
    $$('[data-block-move]').forEach(btn=>btn.onclick=()=>{const n=Number(btn.dataset.blockMove),to=n+Number(btn.dataset.direction);if(to<0||to>=ch.blocks.length)return;[ch.blocks[n],ch.blocks[to]]=[ch.blocks[to],ch.blocks[n]];changed('Ordre des blocs · '+ch.title);renderBook()});
    $$('[data-block-remove]').forEach(btn=>btn.onclick=()=>{ch.blocks=ch.blocks.filter(b=>b.id!==btn.dataset.blockRemove);changed('Bloc retiré · '+ch.title);renderBook();toast('Bloc retiré. Les versions enregistrées le conservent.')});
    $$('[data-add-block]').forEach(btn=>btn.onclick=()=>{const block={id:newId(),type:btn.dataset.addBlock,text:''};ch.blocks.push(block);changed('Bloc ajouté · '+ch.title);renderBook();$(`[data-block-text="${block.id}"]`)?.focus()});$('#insertImage').onclick=imageModal;
    $$('[data-detach-idea]').forEach(btn=>btn.onclick=()=>{ch.ideas=ch.ideas.filter(id=>id!==btn.dataset.detachIdea);changed('Référence retirée · '+ch.title);renderBook()});
  }
};
function blockEditor(b,n){return `<article class="editor-block ${b.type}" data-block="${esc(b.id)}"><div class="block-tools"><span>${{text:'Paragraphe',heading:'Intertitre',quote:'Citation',image:'Illustration',pagebreak:'Saut de page'}[b.type]}</span><button data-block-move="${n}" data-direction="-1" ${n?'':'disabled'} aria-label="Monter le bloc"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m5 12 7-7 7 7M12 5v14"/></svg></button><button data-block-move="${n}" data-direction="1" aria-label="Descendre le bloc"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m5 12 7 7 7-7M12 5v14"/></svg></button><button data-block-remove="${esc(b.id)}" aria-label="Retirer le bloc"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m6 6 12 12M6 18 18 6"/></svg></button></div>${b.type==='image'?`<img src="${assetUrl(b.asset_id)}" alt="${esc(b.alt||b.caption||'Illustration du livre')}"><label>Légende<input data-block-caption="${esc(b.id)}" value="${esc(b.caption||'')}" placeholder="Description, crédit ou source de l’image"></label><label>Largeur<select data-block-width="${esc(b.id)}">${[50,75,100].map(v=>`<option value="${v}" ${Number(b.width||100)===v?'selected':''}>${v} %</option>`).join('')}</select></label>`:b.type==='pagebreak'?'<div class="pagebreak-line">La suite commence sur une nouvelle page</div>':`<textarea data-block-text="${esc(b.id)}" aria-label="${b.type==='heading'?'Intertitre':b.type==='quote'?'Texte de la citation':'Texte du paragraphe'} ${n+1}" placeholder="${b.type==='heading'?'Votre intertitre…':'Écrivez ici…'}" rows="${b.type==='heading'?2:6}">${esc(b.text||'')}</textarea>`}</article>`}
function addChapterToBook(){showModal(`<h2>Nouveau chapitre</h2><form id="newChapterForm"><label>Titre<input name="title" required autofocus placeholder="Le début d’une idée"></label>${formActions('Créer le chapitre')}</form>`);$('#newChapterForm').onsubmit=e=>{e.preventDefault();const title=new FormData(e.target).get('title');const ch={id:newId(),title,notes:'',ideas:[],blocks:[{id:newId(),type:'text',text:''}]};bookDraft.chapters.push(ch);chapterId=ch.id;changed('Chapitre créé · '+title);$('#modal').close();renderBook()}}
function moveChapter(direction){const n=bookDraft.chapters.findIndex(c=>c.id===chapterId),to=n+direction;if(to<0||to>=bookDraft.chapters.length)return;[bookDraft.chapters[n],bookDraft.chapters[to]]=[bookDraft.chapters[to],bookDraft.chapters[n]];changed('Ordre des chapitres');renderBook()}
function deleteChapter(){const ch=currentChapter();showModal(`<h2>Retirer ce chapitre du livre ?</h2><p>${esc(ch.title)} restera dans les versions déjà enregistrées.</p><div class="modal-actions"><button data-close>Conserver</button><button id="confirmChapterRemove">Retirer du livre</button></div>`);$('#confirmChapterRemove').onclick=()=>{bookDraft.chapters=bookDraft.chapters.filter(c=>c.id!==ch.id);changed('Chapitre retiré · '+ch.title);$('#modal').close();renderBook()}}
function bookDetailsModal(){showModal(`<h2>Le livre</h2><form id="bookMetaForm"><label>Titre<input name="title" value="${esc(bookDraft.title)}" required></label><label>Sous-titre<input name="subtitle" value="${esc(bookDraft.subtitle||'')}"></label><label>Auteur<input name="author" value="${esc(bookDraft.author||'')}"></label>${formActions()}</form>`);$('#bookMetaForm').onsubmit=e=>{e.preventDefault();Object.assign(bookDraft,Object.fromEntries(new FormData(e.target)));changed('Informations du livre');$('#modal').close();renderBook()}}
function layoutModal(){const l=bookDraft.layout;showModal(`<h2>Mise en page du livre</h2><p>Format d’impression <strong>A5 · 148 × 210 mm</strong>. La lecture sur téléphone adapte le texte à l’écran, comme une liseuse.</p><form id="layoutForm"><label>Corps du texte PDF<select name="font_size">${[9,10,11,12,13,14,15,16].map(n=>`<option value="${n}" ${Number(l.font_size)===n?'selected':''}>${n} pt</option>`).join('')}</select></label><label>Interligne<select name="line_height">${[1.2,1.4,1.55,1.7,2].map(n=>`<option ${Number(l.line_height)===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Marges<select name="margin">${[10,12,15,17,20,25].map(n=>`<option value="${n}" ${Number(l.margin)===n?'selected':''}>${n} mm</option>`).join('')}</select></label>${formActions('Appliquer')}</form>`);$('#layoutForm').onsubmit=e=>{e.preventDefault();bookDraft.layout={...l,...Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]))};changed('Mise en page A5');$('#modal').close();renderBook()}}
const imageAccept='image/png,image/jpeg,image/webp,image/gif,image/bmp,image/tiff,image/heic,image/heif,.heic,.heif';
async function refreshAssets(){state.assets=await api('assets');return state.assets}
function assetCards(action,label){const images=state.assets||[];return images.length?images.map(a=>`<button class="media-card" data-${action}="${esc(a.id)}" title="${esc(a.name)}"><img src="${assetUrl(a.id)}" alt=""><span>${esc(a.name)}</span>${label?`<small>${label}</small>`:''}</button>`).join(''):'<p class="empty-media">Aucun média pour le moment.</p>'}
function imageModal(){showModal(`<div class="eyebrow">Médiathèque</div><h2>Illustrer le chapitre</h2><p class="small">Choisissez une image déjà importée ou ajoutez-en une nouvelle.</p><div class="media-grid">${assetCards('pick-image')}</div><form id="imageForm"><label>Nouvelle photo ou nouveau schéma<input id="bookImageFile" type="file" accept="${imageAccept}" required></label><label>Légende et crédit<input id="imageCaption" placeholder="Titre, auteur, source…"></label><progress id="imageProgress" max="100" value="0" hidden></progress>${formActions('Importer et insérer')}</form>`);function insert(id,caption=''){currentChapter().blocks.push({id:newId(),type:'image',asset_id:id,caption,alt:caption,width:100});changed('Image ajoutée · '+currentChapter().title);$('#modal').close();renderBook()};$$('[data-pick-image]').forEach(b=>b.onclick=()=>insert(b.dataset.pickImage,b.title));$('#imageForm').onsubmit=e=>{e.preventDefault();run(async()=>{$('#imageProgress').hidden=false;const a=await uploadFile($('#bookImageFile').files[0],{},false,n=>$('#imageProgress').value=n);if(!a.preview)throw Error('Choisissez un fichier image.');await refreshAssets();insert(a.asset_id,$('#imageCaption').value)},e.submitter)}}
function mediaLibraryModal(){showModal(`<div class="eyebrow">Vos fichiers visuels</div><h2>Médiathèque</h2><p class="small">Ces images sont disponibles pour les couvertures, les photos et les schémas de tous vos livres.</p><div class="media-grid media-library-grid">${assetCards('view-media')}</div><form id="mediaUploadForm"><label class="upload-zone"><strong>Ajouter des médias</strong><span>JPEG, PNG, WebP, GIF, BMP, TIFF ou HEIC · 30 Mo par fichier</span><input id="mediaFiles" type="file" accept="${imageAccept}" multiple required></label><progress id="mediaProgress" max="100" value="0" hidden></progress><p id="mediaStatus" class="small"></p>${formActions('Importer')}</form>`);$$('[data-view-media]').forEach(b=>b.onclick=()=>window.open(assetUrl(b.dataset.viewMedia,false),'_blank','noopener'));$('#mediaUploadForm').onsubmit=e=>{e.preventDefault();run(async()=>{const files=[...$('#mediaFiles').files];if(files.length>20)throw Error('Importez au maximum 20 images à la fois.');$('#mediaProgress').hidden=false;for(let n=0;n<files.length;n++){const f=files[n];$('#mediaStatus').textContent=`${n+1}/${files.length} · ${f.name}`;const a=await uploadFile(f,{},false,p=>$('#mediaProgress').value=p);if(!a.preview)throw Error(`${f.name} n’est pas une image prise en charge.`)}await refreshAssets();mediaLibraryModal();toast(`${files.length} média(s) ajouté(s).`)},e.submitter)}}
function coverModal(){const c=bookDraft.covers||(bookDraft.covers={front:'',back:'',front_variants:[],back_variants:[]});const sideHtml=(side,title)=>{const variants=c[side+'_variants'];return `<section class="cover-side"><h3>${title}</h3><div class="cover-variants">${variants.map(id=>{const a=(state.assets||[]).find(x=>x.id===id);return `<button data-select-cover="${esc(id)}" data-cover-side="${side}" class="cover-variant ${c[side]===id?'selected':''}" title="${esc(a?.name||'Couverture')}"><img src="${assetUrl(id)}" alt=""><span>${c[side]===id?'✓ Utilisée':'Utiliser'}</span></button>`}).join('')||'<p class="small">Aucune variante.</p>'}</div><button data-add-cover="${side}">Ajouter une variante</button>${c[side]?`<button class="ghost" data-clear-cover="${side}">Ne pas utiliser de ${title.toLowerCase()}</button>`:''}</section>`};showModal(`<div class="eyebrow">Habillage du livre</div><h2>Couvertures</h2><p class="small">Conservez plusieurs propositions et choisissez celle publiée. La première apparaît au début du PDF et comme couverture officielle de l’EPUB ; la quatrième ferme le livre.</p><div class="cover-editor">${sideHtml('front','Première de couverture')}${sideHtml('back','Quatrième de couverture')}</div><div class="modal-actions"><button data-close>Fermer</button></div>`);$$('[data-select-cover]').forEach(b=>b.onclick=()=>{c[b.dataset.coverSide]=b.dataset.selectCover;changed('Couverture sélectionnée');coverModal()});$$('[data-clear-cover]').forEach(b=>b.onclick=()=>{c[b.dataset.clearCover]='';changed('Couverture retirée');coverModal()});$$('[data-add-cover]').forEach(b=>b.onclick=()=>coverPickerModal(b.dataset.addCover))}
function coverPickerModal(side){showModal(`<h2>Ajouter une variante</h2><p class="small">Choisissez un média existant ou importez une nouvelle image. Un format vertical proche de 2:3 est recommandé.</p><div class="media-grid">${assetCards('cover-pick')}</div><form id="coverUploadForm"><label>Importer une couverture<input id="coverFile" type="file" accept="${imageAccept}" required></label><progress id="coverProgress" max="100" value="0" hidden></progress>${formActions('Importer cette variante')}</form>`);const add=id=>{const c=bookDraft.covers,key=side+'_variants';c[key]=[...new Set([...c[key],id])];c[side]=id;changed((side==='front'?'Première':'Quatrième')+' de couverture ajoutée');coverModal()};$$('[data-cover-pick]').forEach(b=>b.onclick=()=>add(b.dataset.coverPick));$('#coverUploadForm').onsubmit=e=>{e.preventDefault();run(async()=>{$('#coverProgress').hidden=false;const a=await uploadFile($('#coverFile').files[0],{},false,n=>$('#coverProgress').value=n);if(!a.preview)throw Error('Choisissez un fichier image.');await refreshAssets();add(a.asset_id)},e.submitter)}}
async function historyModal(){const history=await api('history');showModal(`<div class="eyebrow">Mémoire du livre</div><h2>Historique des modifications</h2><p class="small">Chaque enregistrement et chaque restauration est conservé. Sélectionnez une version pour voir où le contenu a changé.</p><div class="history-list">${history.map((v,n)=>`<button class="history-entry" data-version="${esc(v.id)}"><span class="history-dot"></span><span><strong>${esc(v.label)}</strong><small>${fullDate(v.created)} · version ${v.seq}${n===0?' · actuelle':''}</small><small>${v.changes.length} changement(s)${v.changes.length?' · '+esc(v.changes.slice(0,2).map(c=>c.label).join(', ')):''}</small></span><span><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 5 7 7-7 7M5 12h14"/></svg></span></button>`).join('')}</div><div class="modal-actions"><button data-close>Fermer</button></div>`);$$('[data-version]').forEach(btn=>btn.onclick=()=>run(()=>versionModal(btn.dataset.version)))}
async function versionModal(id){const v=await api('version?id='+encodeURIComponent(id));showModal(`<div class="row"><button id="historyBack"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 5-7 7 7 7M5 12h14"/></svg> Versions</button><span class="small">${fullDate(v.created)}</span></div><h2 style="margin-top:20px">${esc(v.label)}</h2><div class="diff-legend"><ins>Ajouté</ins><del>Retiré</del></div><div class="version-changes">${v.changes.map(c=>`<section class="diff-section"><h3>${esc(c.label)}</h3>${c.chapter_id?`<button class="ghost small" data-jump-chapter="${esc(c.chapter_id)}" data-jump-block="${esc(c.block_id||'')}">Voir cet emplacement dans le livre actuel ↗</button>`:''}<div class="text-diff">${c.diff.map(d=>d.type==='equal'?esc(d.text):`<${d.type==='insert'?'ins':'del'}>${esc(d.text)}</${d.type==='insert'?'ins':'del'}>`).join('')}</div></section>`).join('')||'<p>Version initiale du livre.</p>'}</div><div class="modal-actions"><button data-close>Fermer</button><button id="restoreVersion" ${state.book._revision===id?'disabled':''}>Restaurer cette version</button></div>`);$('#historyBack').onclick=()=>run(historyModal);$$('[data-jump-chapter]').forEach(btn=>btn.onclick=()=>{if(!bookDraft.chapters.some(c=>c.id===btn.dataset.jumpChapter)){toast('Ce chapitre ne figure plus dans la version actuelle.');return}chapterId=btn.dataset.jumpChapter;$('#modal').close();renderBook();const block=$(`[data-block="${btn.dataset.jumpBlock}"]`);if(block){block.classList.add('highlight-change');block.scrollIntoView({behavior:'smooth',block:'center'})}});$('#restoreVersion').onclick=()=>{showModal(`<h2>Restaurer la version ${v.seq} ?</h2><p>Une nouvelle version sera créée. Votre version actuelle restera accessible dans l’historique.</p><div class="modal-actions"><button data-close>Annuler</button><button class="primary" id="confirmRestore">Restaurer</button></div>`);$('#confirmRestore').onclick=e=>run(async()=>{state.book=await api('restore',{id,revision:state.book._revision});bookDraft=null;bookDirty=false;bookConflict=false;$('#modal').close();renderBook();toast('Version restaurée. L’historique est conservé.')},e.currentTarget)}}
function exportModal(){showModal(`<h2>Emporter votre livre</h2><p>Les illustrations, le texte et les références accompagnent votre livre.</p><div class="export-grid"><button data-export="pdf"><strong>PDF A5</strong><small>148 × 210 mm · impression</small></button><button data-export="epub"><strong>EPUB</strong><small>Lecture sur téléphone et liseuse</small></button><button data-export="md"><strong>Markdown</strong><small>Texte et références pour retravailler</small></button></div><div class="modal-actions"><button data-close>Fermer</button></div>`);$$('[data-export]').forEach(btn=>btn.onclick=()=>run(async()=>{await persistDraft();btn.disabled=true;btn.textContent='Préparation…';const kind=btn.dataset.export;const res=await fetch((kind==='md'?'/api/export':'/api/book.'+kind)+'?book_id='+encodeURIComponent(activeBookId));if(!res.ok){const err=await res.json();throw Error(err.error||'Export impossible.')}const blob=await res.blob(),a=document.createElement('a'),link=URL.createObjectURL(blob);a.href=link;a.download='mon-livre'+(kind==='pdf'?'-A5':'')+'.'+kind;a.click();setTimeout(()=>URL.revokeObjectURL(link),5000);$('#modal').close();toast('Export prêt.')},btn))}

async function openSourcePages(s){let blocks=s.reading?.length?s.reading:s.segments.map(x=>({type:'text',text:x.text}));await openPages({title:s.title,author:s.author,sections:[{title:s.title,blocks}],book:false})}
async function openPages(data){
  reading=data;readingIndex=0;
  const overlay=document.createElement('section');overlay.id='readingOverlay';overlay.className='reading-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Lecture paginée');
  overlay.innerHTML=`<header class="reading-header"><button id="closeReading" aria-label="Fermer la lecture"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 5-7 7 7 7M5 12h14"/></svg></button><div><strong>${esc(data.title)}</strong><small>${data.book?'Aperçu de lecture · le PDF conserve le format A5':'Lecture du document'}</small></div><button id="readerToc"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></svg> Sommaire</button><button id="smallerFont" aria-label="Réduire le texte">A−</button><button id="largerFont" aria-label="Agrandir le texte">A+</button></header><div class="reader-toc" id="readerContents" hidden></div><div class="page-stage"><div id="pageFrame" class="page-frame"><div id="pageContent" class="page-content"></div><footer id="pageFooter"></footer></div></div><footer class="reading-controls"><button id="previousPage" aria-label="Page précédente"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 5-7 7 7 7M5 12h14"/></svg></button><input id="pageSlider" type="range" min="1" max="1" value="1" aria-label="Aller à la page"><span id="pagePosition" aria-live="polite">Mise en page…</span><button id="nextPage" aria-label="Page suivante"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m12 5 7 7-7 7M5 12h14"/></svg></button></footer><div id="pageMeasure" class="page-content page-measure" aria-hidden="true"></div>`;
  document.body.append(overlay);document.body.classList.add('reading-open');$('#app').inert=true;readingAbort=new AbortController();const signal=readingAbort.signal;
  $('#closeReading').onclick=closePages;$('#closeReading').focus();$('#readerToc').onclick=()=>$('#readerContents').hidden=!$('#readerContents').hidden;
  $('#previousPage').onclick=()=>turnPage(-1);$('#nextPage').onclick=()=>turnPage(1);$('#pageSlider').oninput=e=>{readingIndex=Number(e.target.value)-1;showPage()};
  $('#smallerFont').onclick=()=>{readingFont=Math.max(13,readingFont-1);paginate()};$('#largerFont').onclick=()=>{readingFont=Math.min(24,readingFont+1);paginate()};
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closePages();else if(e.key==='ArrowRight')turnPage(1);else if(e.key==='ArrowLeft')turnPage(-1);else if(e.key==='Tab'){const focus=[...overlay.querySelectorAll('button:not(:disabled),input')].filter(x=>x.offsetParent!==null),first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}},{signal});
  let start=null;$('#pageFrame').addEventListener('touchstart',e=>{start={x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY}},{passive:true,signal});$('#pageFrame').addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start.x,dy=e.changedTouches[0].clientY-start.y;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.4)turnPage(dx<0?1:-1);start=null},{passive:true,signal});
  window.addEventListener('resize',()=>{clearTimeout(readingResize);readingResize=setTimeout(paginate,180)},{signal});
  if(document.fonts?.ready)await document.fonts.ready;await paginate();
}
let pageList=[],tocEntries=[];
async function paginate(){
  if(!reading||!$('#pageFrame'))return;
  const frame=$('#pageFrame'),content=$('#pageContent'),measure=$('#pageMeasure');frame.style.setProperty('--read-font',readingFont+'px');
  const width=content.clientWidth,height=content.clientHeight;measure.style.width=width+'px';measure.style.height=height+'px';measure.style.fontSize=readingFont+'px';measure.style.lineHeight='1.58';
  if(!width||!height)return;
  pageList=[];tocEntries=[];let page='';measure.innerHTML='';
  const flush=()=>{if(page){pageList.push(page);page='';measure.innerHTML=''}};
  const fits=html=>{measure.innerHTML=page+html;return measure.scrollHeight<=height+1};
  const addText=(text,tag='p')=>{
    let words=String(text).split(/\s+/).filter(Boolean);if(!words.length)return;
    while(words.length){const full=`<${tag}>${esc(words.join(' '))}</${tag}>`;if(fits(full)){page+=full;break}
      let lo=0,hi=words.length;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(fits(`<${tag}>${esc(words.slice(0,mid).join(' '))}</${tag}>`))lo=mid;else hi=mid-1}
      if(lo===0&&page){flush();continue}if(lo===0)lo=1;
      page+=`<${tag}>${esc(words.slice(0,lo).join(' '))}</${tag}>`;words=words.slice(lo);flush();
    }
  };
  if(reading.book){addText(reading.title,'h1');if(reading.subtitle)addText(reading.subtitle);if(reading.author)addText(reading.author);flush()}
  for(const section of reading.sections){flush();tocEntries.push({title:section.title,page:pageList.length});addText(section.title,'h1');
    for(const block of section.blocks){
      if(block.type==='pagebreak'){flush();continue}
      if(block.type==='image'){
        const im=new Image();im.src=assetUrl(block.asset_id);await new Promise(resolve=>{im.onload=resolve;im.onerror=resolve;if(im.complete)resolve()});
        const ratio=(im.naturalHeight||600)/(im.naturalWidth||800),desired=Math.min(width*(Number(block.width)||100)/100,(height-75)/ratio),imageHeight=desired*ratio;
        const figure=`<figure><img src="${assetUrl(block.asset_id)}" alt="${esc(block.alt||block.caption||'Illustration')}" style="width:${desired}px;height:${imageHeight}px"><figcaption>${esc(block.caption||'')}</figcaption></figure>`;
        if(!fits(figure))flush();if(fits(figure))page+=figure;else{const reduced=figure.replace(`height:${imageHeight}px`,`height:${Math.max(60,height-120)}px`);page+=reduced}continue;
      }
      for(const paragraph of String(block.text||'').split(/\n\s*\n/))addText(paragraph,block.type==='heading'?'h2':block.type==='quote'?'blockquote':'p');
    }
  }flush();if(!pageList.length)pageList=['<p>Ce livre ne contient pas encore de texte.</p>'];
  readingIndex=Math.min(readingIndex,pageList.length-1);$('#pageSlider').max=pageList.length;$('#readerContents').innerHTML=tocEntries.map(t=>`<button data-toc-page="${t.page}"><span>${esc(t.title)}</span><small>${t.page+1}</small></button>`).join('');$$('[data-toc-page]').forEach(btn=>btn.onclick=()=>{readingIndex=Number(btn.dataset.tocPage);showPage();$('#readerContents').hidden=true});showPage();
}
function showPage(){if(!$('#pageContent'))return;$('#pageContent').innerHTML=pageList[readingIndex];$('#pageFooter').textContent=readingIndex+1;$('#pagePosition').textContent=`${readingIndex+1} / ${pageList.length}`;$('#pageSlider').value=readingIndex+1;$('#previousPage').disabled=readingIndex===0;$('#nextPage').disabled=readingIndex===pageList.length-1}
function turnPage(direction){const next=readingIndex+direction;if(next<0||next>=pageList.length)return;readingIndex=next;showPage();const frame=$('#pageFrame');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)frame.animate([{opacity:.5,transform:`translateX(${direction*14}px)`},{opacity:1,transform:'translateX(0)'}],{duration:180})}
function closePages(){readingAbort?.abort();clearTimeout(readingResize);reading=null;$('#readingOverlay')?.remove();document.body.classList.remove('reading-open');$('#app').inert=false;$('#readBook')?.focus()}

addToBookModal=function(id){
  let targetBook=state.book;
  showModal(`<h2>Ajouter une idée à un livre</h2><form id="addBookForm"><label>Projet de livre<select id="ideaBookProject">${(state.books||[]).map(b=>`<option value="${esc(b.id)}" ${b.id===state.book._book_id?'selected':''}>${esc(b.title)}</option>`).join('')}</select></label><label>Chapitre<select id="targetChapter"></select></label><p id="targetChapterNotice" class="small"></p>${formActions('Ajouter au chapitre')}</form>`);
  function fill(){const ch=targetBook.chapters;$('#targetChapter').innerHTML=ch.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('');$('#targetChapterNotice').textContent=ch.length?'Les références de cette idée seront conservées.':'Créez d’abord un chapitre dans ce projet de livre.';$('#addBookForm button[type=submit]').disabled=!ch.length}fill();
  $('#ideaBookProject').onchange=e=>run(async()=>{targetBook=await api('book?book_id='+encodeURIComponent(e.target.value));fill()});
  $('#addBookForm').onsubmit=e=>{e.preventDefault();run(async()=>{const ch=targetBook.chapters.find(c=>c.id===$('#targetChapter').value);ch.ideas=[...new Set([...ch.ideas,id])];const saved=await api('book',targetBook);if(saved._book_id===state.book._book_id){state.book=saved;bookDraft=null}$('#modal').close();toast('Idée ajoutée à « '+saved.title+' ».')},e.submitter)};
};
